const input = $input.first()?.json ?? {};
const raw = input.output ?? input.text ?? input;

const parseLead = (value) => {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;

  const text = String(value ?? '').trim();
  if (!text) return {};

  const withoutFence = text
    .replace(/^\x60\x60\x60(?:json)?/i, '')
    .replace(/\x60\x60\x60$/i, '')
    .trim();
  const match = withoutFence.match(/\{[\s\S]*\}/);
  if (!match) return {};

  try {
    const parsed = JSON.parse(match[0]);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    return {};
  }
};

const pick = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).replace(/\s+/g, ' ').trim();
  return text === '' ? null : text;
};

const normalizePhone = (value) => {
  const text = pick(value);
  if (!text) return null;

  let phone = text.replace(/[^\d+]/g, '');
  if (phone.startsWith('+84')) phone = '0' + phone.slice(3);
  if (phone.startsWith('84') && phone.length >= 11) phone = '0' + phone.slice(2);

  return /^0\d{8,10}$/.test(phone) ? phone : null;
};

const normalizeInteger = (value, min, max) => {
  const text = pick(value);
  if (!text) return null;
  const match = text.match(/\d{1,4}/);
  if (!match) return null;
  const number = Number(match[0]);
  if (!Number.isInteger(number) || number < min || number > max) return null;
  return number;
};

const normalizeLeadScore = (value, phone) => {
  const score = pick(value)?.toLowerCase();
  if (['hot', 'warm', 'not_interested'].includes(score)) return score;
  return phone ? 'hot' : null;
};

const ext = parseLead(raw);
const chatId = pick($('Execute Sub-workflow Trigger').first()?.json?.chat_id);

if (!chatId) {
  throw new Error('Missing normalized Zalo chat ID');
}

const phone = normalizePhone(ext.phone);

return [{
  json: {
    zalo_id: chatId,
    name: pick(ext.name),
    phone,
    birth_year: normalizeInteger(ext.birth_year, 1900, new Date().getFullYear()),
    age: normalizeInteger(ext.age, 15, 80),
    living_area: pick(ext.living_area),
    address: pick(ext.address),
    gender: pick(ext.gender),
    region: pick(ext.region),
    desired_job: pick(ext.desired_job),
    years_experience: pick(ext.years_experience),
    latest_company: pick(ext.latest_company),
    expected_salary: pick(ext.expected_salary),
    lead_score: normalizeLeadScore(ext.lead_score, phone),
  },
}];

const row = $input.first()?.json ?? {};
return [{
  json: {
    ok: true,
    zalo_id: row.zalo_id ?? $('Execute Sub-workflow Trigger').first()?.json?.chat_id ?? null,
    lead_score: row.lead_score ?? null,
    phone_present: Boolean(row.phone),
  },
}];
